package com.gabbymaybelle.forgemark;

import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.tags.TagKey;
import net.minecraft.world.item.Item;

/** Tags pack makers can fill. The metal tags are generated by {@code tools/gen-data.js}. */
public final class ForgemarkTags {
	/** Items that can never be tempered, for special gear such as Botania's relics. */
	public static final TagKey<Item> NOT_TEMPERABLE = item("not_temperable");
	/** What the hearth will heat: ingots and gems, so anything repaired with them can be tempered. */
	public static final TagKey<Item> HEATABLE = item("heatable");
	/** Metals that reach forging heat in 6 seconds instead of 10 (gold, copper). */
	public static final TagKey<Item> HEATS_QUICKLY = item("heats_quickly");
	/** Metals that take 20 seconds (netherite, diamond). */
	public static final TagKey<Item> HEATS_SLOWLY = item("heats_slowly");
	/** Metals that take 2 strikes per heat instead of 3 (gold). */
	public static final TagKey<Item> SOFT_METAL = item("soft_metal");
	/** Metals that take 4 strikes per heat (netherite, diamond). */
	public static final TagKey<Item> HARD_METAL = item("hard_metal");
	/** Anything that strikes the forging anvil. */
	public static final TagKey<Item> HAMMERS = item("hammers");

	private ForgemarkTags() {
	}

	private static TagKey<Item> item(String name) {
		return TagKey.create(Registries.ITEM, ResourceLocation.fromNamespaceAndPath(Forgemark.MOD_ID, name));
	}
}
